// AMD module: block_pharos_teacher/teacher-dashboard (ES5 build)
define([], function () {
    'use strict';

    function init() {
        var root = document.querySelector('.pharos-teacher-dashboard');
        if (!root) { return; }
        animateXpBars(root);
        initAiDetailButtons(root);
        initAdvisorButtons(root);
        initMotivateButtons(root);
    }

    function animateXpBars(root) {
        var bars = root.querySelectorAll('[data-xp-target]');
        if (!bars.length) { return; }
        var observer = new IntersectionObserver(function (entries) {
            entries.forEach(function (entry) {
                if (!entry.isIntersecting) { return; }
                var container = entry.target;
                var fill = container.querySelector('.pharos-xp-bar__fill');
                if (!fill) { return; }
                requestAnimationFrame(function () {
                    fill.style.transition = 'width 0.5s ease';
                    fill.style.width = container.dataset.xpTarget + '%';
                });
                observer.unobserve(container);
            });
        }, { threshold: 0.1 });
        bars.forEach(function (bar) { observer.observe(bar); });
    }

    function initAiDetailButtons(root) {
        var detailUrl = root.dataset.aiDetailUrl;
        var sesskey = root.dataset.sesskey;
        if (!detailUrl) { return; }
        var modal = document.getElementById('pharos-ai-detail-modal');
        var modalTitle = document.getElementById('pharos-ai-detail-title');
        var modalBody = document.getElementById('pharos-ai-detail-body');
        if (!modal || !modalTitle || !modalBody) { return; }
        root.addEventListener('click', function (e) {
            var btn = e.target.closest('.pharos-ai-detail-btn');
            if (!btn) { return; }
            var studentId = btn.dataset.studentId;
            var courseId = new URLSearchParams(new URL(detailUrl).search).get('courseid');
            modalTitle.textContent = btn.dataset.studentName;
            modalBody.innerHTML = '<div class="text-center py-3"><div class="spinner-border text-danger" role="status"><span class="sr-only">…</span></div></div>';
            showModal(modal);
            fetch(detailUrl, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ sesskey: sesskey, courseid: courseId, student_id: studentId }) })
            .then(function (r) { return r.json(); })
            .then(function (data) { modalBody.innerHTML = data.error ? '<p class="text-danger">' + data.error + '</p>' : renderAiDetail(data); })
            .catch(function () { modalBody.innerHTML = '<p class="text-danger">Error al cargar los datos.</p>'; });
        });
        modal.addEventListener('click', function (e) { if (e.target.closest('[data-dismiss="modal"]') || e.target === modal) { hideModal(modal); } });
    }

    function renderAiDetail(data) {
        var levelColors = { 1: '#C8102E', 2: '#e07b00', 3: '#0D1520' };
        var html = '<div class="d-flex mb-3 text-center">' + stat(data.total_sessions, 'Sesiones') + stat(data.total_messages, 'Mensajes') + stat(data.total_minutes + ' min', 'Tiempo') + '</div>';
        if (!data.sessions || !data.sessions.length) { return html + '<p class="text-muted small">Sin sesiones en los últimos 30 días.</p>'; }
        html += '<p class="text-muted small mb-1">Últimas 30 días:</p><table class="table table-sm table-borderless mb-0"><thead><tr><th class="small">Fecha</th><th class="small">Nivel</th><th class="small text-right">Msg</th><th class="small text-right">Min</th></tr></thead><tbody>';
        data.sessions.forEach(function (s) {
            var c = levelColors[s.level] || '#999';
            html += '<tr><td class="small text-muted" style="white-space:nowrap">' + s.date + '</td><td><span class="badge" style="background:' + c + ';color:#fff">' + s.level_label + '</span></td><td class="small text-right">' + s.message_count + '</td><td class="small text-right">' + s.duration_min + '</td></tr>';
        });
        return html + '</tbody></table>';
    }

    function stat(value, label) {
        return '<div class="flex-fill text-center"><p class="h5 mb-0 text-danger">' + value + '</p><small class="text-muted">' + label + '</small></div>';
    }

    var advisorState = { studentId: null, studentName: null, courseId: null, messages: [], sending: false };

    function initAdvisorButtons(root) {
        var advisorUrl = root.dataset.advisorUrl;
        var sesskey    = root.dataset.sesskey;
        var lang       = root.dataset.advisorLang || 'es';
        if (!advisorUrl) { return; }
        var modal    = document.getElementById('pharos-advisor-modal');
        var subtitle = modal && modal.querySelector('.pharos-advisor-subtitle');
        var msgBox   = document.getElementById('pharos-advisor-messages');
        var input    = document.getElementById('pharos-advisor-input');
        var sendBtn  = document.getElementById('pharos-advisor-send');
        if (!modal || !msgBox || !input || !sendBtn) { return; }
        var courseId = new URLSearchParams(new URL(advisorUrl).search).get('courseid');
        root.addEventListener('click', function (e) {
            var btn = e.target.closest('.pharos-advisor-btn');
            if (!btn) { return; }
            advisorState.studentId = btn.dataset.studentId; advisorState.studentName = btn.dataset.studentName; advisorState.courseId = courseId; advisorState.messages = [];
            if (subtitle) { subtitle.textContent = advisorState.studentName; }
            msgBox.innerHTML = ''; input.value = '';
            showModal(modal); input.focus();
        });
        sendBtn.addEventListener('click', function () { sendAdvisorMessage(advisorUrl, sesskey, lang, msgBox, input, sendBtn); });
        input.addEventListener('keydown', function (e) { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendAdvisorMessage(advisorUrl, sesskey, lang, msgBox, input, sendBtn); } });
        modal.addEventListener('click', function (e) { if (e.target.closest('[data-dismiss="modal"]') || e.target === modal) { hideModal(modal); } });
    }

    function sendAdvisorMessage(advisorUrl, sesskey, lang, msgBox, input, sendBtn) {
        if (advisorState.sending) { return; }
        var text = input.value.trim();
        if (!text) { return; }
        advisorState.messages.push({ role: 'user', content: text });
        appendMessage(msgBox, 'user', text);
        input.value = ''; advisorState.sending = true; sendBtn.disabled = true;
        var typingId = appendTyping(msgBox);
        fetch(advisorUrl, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ sesskey: sesskey, courseid: advisorState.courseId, student_id: advisorState.studentId, lang: lang, messages: advisorState.messages }) })
        .then(function (r) { return r.json(); })
        .then(function (data) { removeTyping(msgBox, typingId); if (data.error) { appendMessage(msgBox, 'error', data.error); } else { advisorState.messages.push({ role: 'assistant', content: data.reply }); appendMessage(msgBox, 'assistant', data.reply); } })
        .catch(function () { removeTyping(msgBox, typingId); appendMessage(msgBox, 'error', 'Error de conexión. Inténtalo de nuevo.'); })
        .finally(function () { advisorState.sending = false; sendBtn.disabled = false; input.focus(); });
    }

    function appendMessage(msgBox, role, text) { var div = document.createElement('div'); div.className = 'pharos-advisor-msg pharos-advisor-msg--' + role; div.textContent = text; msgBox.appendChild(div); msgBox.scrollTop = msgBox.scrollHeight; }
    function appendTyping(msgBox) { var id = 'pharos-typing-' + Date.now(); var div = document.createElement('div'); div.id = id; div.className = 'pharos-advisor-msg pharos-advisor-msg--typing'; div.setAttribute('aria-label', 'Escribiendo…'); div.innerHTML = '<span></span><span></span><span></span>'; msgBox.appendChild(div); msgBox.scrollTop = msgBox.scrollHeight; return id; }
    function removeTyping(msgBox, id) { var el = document.getElementById(id); if (el) { el.remove(); } }

    function initMotivateButtons(root) {
        var motivateUrl = root.dataset.motivateUrl;
        var sesskey     = root.dataset.sesskey;
        var lang        = root.dataset.advisorLang || 'es';
        if (!motivateUrl) { return; }
        var modal    = document.getElementById('pharos-motivate-modal');
        var subtitle = modal && modal.querySelector('.pharos-motivate-subtitle');
        var loading  = document.getElementById('pharos-motivate-loading');
        var result   = document.getElementById('pharos-motivate-result');
        var message  = document.getElementById('pharos-motivate-message');
        var copyBtn  = document.getElementById('pharos-motivate-copy');
        var sendLink = document.getElementById('pharos-motivate-send-link');
        var errorBox = document.getElementById('pharos-motivate-error');
        if (!modal || !loading || !result || !message || !copyBtn || !sendLink || !errorBox) { return; }
        var courseId = new URLSearchParams(new URL(motivateUrl).search).get('courseid');
        root.addEventListener('click', function (e) {
            var btn = e.target.closest('.pharos-motivate-btn');
            if (!btn) { return; }
            var studentId = btn.dataset.studentId; var studentName = btn.dataset.studentName; var messageUrl = btn.dataset.messageUrl;
            if (subtitle) { subtitle.textContent = studentName; }
            loading.classList.remove('d-none'); result.classList.add('d-none'); errorBox.classList.add('d-none'); message.textContent = '';
            showModal(modal);
            fetch(motivateUrl, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ sesskey: sesskey, courseid: parseInt(courseId, 10), student_id: parseInt(studentId, 10), lang: lang }) })
            .then(function (r) { return r.json(); })
            .then(function (data) { loading.classList.add('d-none'); if (data.error) { errorBox.textContent = data.error; errorBox.classList.remove('d-none'); } else { message.textContent = data.message; sendLink.href = data.message_url || messageUrl; result.classList.remove('d-none'); } })
            .catch(function () { loading.classList.add('d-none'); errorBox.textContent = 'Error de conexión. Inténtalo de nuevo.'; errorBox.classList.remove('d-none'); });
        });
        copyBtn.addEventListener('click', function () {
            var text = message.textContent; if (!text) { return; }
            if (navigator.clipboard && navigator.clipboard.writeText) { navigator.clipboard.writeText(text).then(function () { copyBtn.textContent = '✓'; setTimeout(function () { copyBtn.textContent = copyBtn.dataset.label || 'Copiar'; }, 2000); }); }
            else { var ta = document.createElement('textarea'); ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); document.body.removeChild(ta); copyBtn.textContent = '✓'; setTimeout(function () { copyBtn.textContent = copyBtn.dataset.label || 'Copiar'; }, 2000); }
        });
        modal.addEventListener('click', function (e) { if (e.target.closest('[data-dismiss="modal"]') || e.target === modal) { hideModal(modal); } });
    }

    function showModal(modal) { if (typeof $ !== 'undefined') { $(modal).modal('show'); } else { modal.classList.add('show'); modal.style.display = 'block'; document.body.classList.add('modal-open'); } }
    function hideModal(modal) { if (typeof $ !== 'undefined') { $(modal).modal('hide'); } else { modal.classList.remove('show'); modal.style.display = ''; document.body.classList.remove('modal-open'); } }

    return { init: init };
});
